sp_theme.css_variables:
// SCSS variables — compiled at build time, so these must be
// literal hex values. They cannot reference the CSS custom
// properties in the include; that's a different layer.

$body-bg:        #F6F2EA;
$text-color:     #3A342C;
$brand-primary:  #B0705A;
$brand-color:    #B0705A;
$link-color:     #B0705A;
$link-hover-color: #99604C;

$panel-bg:           #FFFDF9;
$panel-default-border: #E2DACC;

// Header bar. Stock SP headers use the inverse navbar classes.
$navbar-inverse-bg:               #FFFDF9;
$navbar-inverse-color:            #6B6157;
$navbar-inverse-link-color:       #6B6157;
$navbar-inverse-link-hover-color: #3A342C;
$navbar-inverse-link-active-bg:   transparent;
$navbar-inverse-border:           #E2DACC;
